def run_application_simulated_verifications(
    db: Session,
    application: Application
) -> List[Dict[str, Any]]:
    """
    Orchestrates automated simulated external verifications across the 4 statutory authorities.
    Records findings in MySQL for any detected mismatch or failure scenario.
    """
    inst_name = application.institution.name if application.institution else "Applicant Institution"
    
    # Locate relevant extracted registration and NOC numbers
    docs = db.query(Document).filter(Document.application_id == application.id).all()
    reg_numbers = []
    noc_numbers = []
    for d in docs:
        for ef in d.extracted_fields:
            if ef.field_name == "registration_number" and ef.extracted_value:
                reg_numbers.append(ef.extracted_value.strip())
            elif ef.field_name == "noc_reference" and ef.extracted_value:
                noc_numbers.append(ef.extracted_value.strip())

    sample_reg = reg_numbers[0] if reg_numbers else "MAH/2026/REG/5512"
    sample_noc = noc_numbers[0] if noc_numbers else "FIRE/NOC/2026/7821"

    # 1. Society Registry
    soc_res = verify_society_registration(sample_reg, inst_name)
    # 2. Fire Safety NOC
    fire_res = verify_fire_safety_noc(sample_noc, inst_name)
    # 3. University Affiliation
    univ_res = verify_university_affiliation(
        application.application_number,
        application.total_intake_declared or 0,
        application.academic_year or "2026-2027"
    )
    # 4. Land Records
    land_res = verify_land_records(application.land_area_acres or 0.0, inst_name)

    results = [soc_res, fire_res, univ_res, land_res]

    # Clean previous un-resolved external verification findings for safe idempotency
    db.query(ComplianceFinding).filter(
        ComplianceFinding.application_id == application.id,
        ComplianceFinding.finding_type == "External Verification Mismatch",
        ComplianceFinding.status != "Resolved"
    ).delete(synchronize_session=False)

    for r in results:
        if r["status"] in ["Mismatch", "Not Found"]:
            finding = ComplianceFinding(
                application_id=application.id,
                finding_type="External Verification Mismatch",
                title=f"External Registry Exception: {r['registry_name']}",
                description=f"{r['details']} (Notice: {SIMULATION_DISCLAIMER})",
                severity="High" if r["status"] == "Mismatch" else "Medium",
                status="Open",
                expected_value=f"Verified status with {r['registry_name']}",
                observed_value=f"Status: {r['status']}",
                recommended_action=f"Obtain official authentication clearance from {r['registry_name']}."
            )
            db.add(finding)

    db.commit()
    return results

